    'coachmark.decisionRoom.title': "President's Desk",
    'coachmark.decisionRoom.body': 'Review pending decisions and staff handoffs before you advance the week.',
    'coachmark.operationOpportunity.title': 'Operation Opportunity',
    'coachmark.operationOpportunity.body': 'Authorize, redirect, delay, or decline staff-proposed operations from their dossier.',
    'coachmark.chronicleFilter.title': 'Chronicle Filters',
    'coachmark.chronicleFilter.body': 'Filter the campaign record when you need to reconstruct why the front changed.',
    'coachmark.codex.title': 'Codex',
    'coachmark.codex.body': 'Open historical context and reference essays without leaving the tactical map.',
    'onboarding.stepCount': 'Step {index} of {total}',
    'onboarding.skip': 'Skip Tutorial',
    'onboarding.next': 'Next',
    'onboarding.finish': 'Finish',
    'onboarding.restart': 'Restart Tutorial',
    'onboarding.01.title': 'A War You Cannot Win',
    'onboarding.01.body': "You are the president of a country at war, not a conqueror chasing a map. There is no victory screen here. This war is negative-sum: it can only be survived, ended, or made worse. Your task is to author how the tragedy unfolds - and how heavy a price it leaves behind.",
    'onboarding.02.title': 'The Map Is Not the Score',
    'onboarding.02.body': 'Faction colors show political control; front edges mark where your forces meet the enemy. But do not play for the map. Over years of fighting the front can barely move while the country empties out - hundreds of thousands displaced to shift the line a few settlements. Land is not the scoreboard.',
    'onboarding.03.title': 'The Brief',
    'onboarding.03.body': "The field toolbar keeps map inspection close: WAR MAP gives the field situation, RECORDS opens the Army HQ records view, and CODEX keeps historical context close. Read the desk packet first; the President's Desk is where inspection becomes action.",
    'onboarding.04.title': 'Inspect Before You Decide',
    'onboarding.04.body': 'The Warroom status bar shows the current phase, priorities, and pending reviews. The priority docket lists what your staff flags as urgent. Open Army HQ to drill into corps readiness, supply, and command friction before you commit.',
    'onboarding.05.title': "President's Desk",
    'onboarding.05.body': "Before you advance the turn, the President's Desk surfaces every pending choice. Each row opens its resolver or the staff panel it came from -- open it, decide, return. Resolve what you can; defer what you must.",
    'onboarding.06.title': 'You Command Through Generals',
    'onboarding.06.body': "You command through your generals, not over individual units. You never push brigades yourself - every assault flows through a corps operation. Your commanders propose operations; you approve, decline, or force-launch over their judgment at the cost of command authority. You set direction and bear the consequences; they fight the battle.",
    'onboarding.07.title': 'Advance and Read the Aftermath',
    'onboarding.07.body': 'When you advance the turn, the war moves forward by one week. The aftermath panel reports what changed: battles fought, ground won or lost, casualties, the displaced, command outcomes. Read it - the human cost is part of the record, not a footnote. The next turn begins with the consequences of this one.',
    'onboarding.08.title': 'The Cost Ledger Is the Scoreboard',
    'onboarding.08.body': 'The war-cost ledger is your real scoreboard, not the map. Seizing territory can lower your final grade; the displaced and the exhausted weigh against you, and atrocity taints the verdict permanently - it is never rewarded. The war climaxes at the Dayton table, where you spend hard-won leverage across the peace. That settlement is where you are judged.',
    'aar.title': 'After-Action Report',
    'aar.close': 'Close After-Action Report',
    'aar.noReport': 'No report yet - advance a turn to generate the first AAR.',
