    'inbox.openingBrief.thesis': "This war has no conquest victory. The map can hold flat while the country is destroyed - you are judged at the Dayton table by the war's human cost, not by territory.",
    'inbox.openingBrief.RBiH.title': 'Republic of Bosnia and Herzegovina',
    'inbox.openingBrief.RBiH.bullet.0': 'Hold Sarajevo, Tuzla, Zenica, Bihac, and other urban anchors while the army forms under fire.',
    'inbox.openingBrief.RBiH.bullet.1': 'Keep the international record visible: diplomacy, civilian harm, and military survival are linked.',
    'inbox.openingBrief.RBiH.bullet.2': 'Use Army HQ and the Decision Room to set priorities and approve operations through commanders.',
    'inbox.openingBrief.RS.title': 'Republika Srpska',
    'inbox.openingBrief.RS.bullet.0': 'Exploit inherited JNA armor, artillery, and logistics before international pressure narrows the window.',
    'inbox.openingBrief.RS.bullet.1': 'Secure connected territory and protect the Posavina corridor linking eastern and western holdings.',
    'inbox.openingBrief.RS.bullet.2': 'Use Army HQ and the Decision Room to balance offensive pressure against exhaustion and legitimacy cost.',
